            end do
         end do
         do gi = 1, 1
            ic = rc3(gi)
            do ia = 0, 5
               !$acc atomic update
               jmat(idens, mui + ia, lamk + ic) = jmat(idens, mui + ia, lamk + ic) &
                                           + kac(1 + ia + 6*ic)
            end do
         end do
         do id = 0, 2
            do ia = 0, 5
               !$acc atomic update
               jmat(idens, mui + ia, sigl + id) = jmat(idens, mui + ia, sigl + id) &
                                           + kad(1 + ia + 6*id)
            end do
