         do gi = 1, 1
            ic = rc3(gi)
            do ib = 0, 2
               !$acc atomic update
               jmat(idens, nuj + ib, lamk + ic) = jmat(idens, nuj + ib, lamk + ic) &
                                           + kbc(1 + ib + 3*ic)
            end do
         end do
         do id = 0, 2
            do ib = 0, 2
               !$acc atomic update
               jmat(idens, nuj + ib, sigl + id) = jmat(idens, nuj + ib, sigl + id) &
                                           + kbd(1 + ib + 3*id)
