            end do
         end do
         do gi = 1, 1
            ic = rc4(gi)
            do ia = 0, 5
               !$acc atomic update
               jmat(idens, mui + ia, lamk + ic) = jmat(idens, mui + ia, lamk + ic) &
                                           + kac(1 + ia + 6*ic)
            end do
